#include <bits/stdc++.h>
using namespace std;

bool isPrime(long long n) {
    if (n < 2) return false;             // 0 和 1 都不是质数
    for (long long i = 2; i * i <= n; i++) {
        if (n % i == 0) return false;    // 找到非 1 和自身的因数
    }
    return true;
}

int main() {
    long long n;
    cin >> n;
    cout << (isPrime(n) ? "prime" : "not prime") << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n;
    cin >> n;

    for (long long i = 2; i * i <= n; i++) {
        while (n % i == 0) {
            cout << i << " "; // i 是当前找到的质因子
            n /= i;            // 把这个因子从 n 中去掉
        }
    }

    if (n > 1) {
        cout << n << " ";     // 剩下的大于 1 的数也是质因子
    }
    return 0;
}
